81	export function accumulateTokenUsage(
82	  target: TokenUsage,
83	  update: Partial<TokenUsage> | undefined,
84	  incrementRequests = false,
85	): void {
86	  if (!update) {
87	    return;
88	  }
89	
90	  // Accumulate basic fields
91	  target.prompt = addNumbers(target.prompt, update.prompt);
92	  target.completion = addNumbers(target.completion, update.completion);
93	  target.cached = addNumbers(target.cached, update.cached);
94	  target.total = addNumbers(target.total, update.total);
95	
96	  // Handle numRequests
97	  if (update.numRequests !== undefined) {
98	    target.numRequests = addNumbers(target.numRequests, update.numRequests);
99	  } else if (incrementRequests) {
100	    target.numRequests = (target.numRequests ?? 0) + 1;
101	  }
102	
103	  // Handle completion details
104	  if (update.completionDetails) {
105	    target.completionDetails = accumulateCompletionDetails(
106	      target.completionDetails,
107	      update.completionDetails,
108	    );
109	  }
110	
111	  // Handle assertions
112	  if (update.assertions) {
113	    if (!target.assertions) {
114	      target.assertions = {
115	        total: 0,
116	        prompt: 0,
117	        completion: 0,
118	        cached: 0,
119	        numRequests: 0,
120	      };
121	    }
122	
123	    target.assertions.total = addNumbers(target.assertions.total, update.assertions.total);
124	    target.assertions.prompt = addNumbers(target.assertions.prompt, update.assertions.prompt);
125	    target.assertions.completion = addNumbers(
126	      target.assertions.completion,
127	      update.assertions.completion,
128	    );
129	    target.assertions.cached = addNumbers(target.assertions.cached, update.assertions.cached);
130	    target.assertions.numRequests = addNumbers(
131	      target.assertions.numRequests,
132	      update.assertions.numRequests,
133	    );
134	
135	    if (update.assertions.completionDetails) {
136	      target.assertions.completionDetails = accumulateCompletionDetails(
137	        target.assertions.completionDetails,
138	        update.assertions.completionDetails,
139	      );
140	    }
141	  }
142	}
