144	/**
145	 * Accumulate token usage specifically for assertions.
146	 * This function operates directly on an assertions object rather than a full TokenUsage object.
147	 * @param target Assertions object to update
148	 * @param update Partial token usage that may contain assertion-related fields
149	 */
150	export function accumulateAssertionTokenUsage(
151	  target: NonNullable<TokenUsage['assertions']>,
152	  update: Partial<TokenUsage> | undefined,
153	): void {
154	  if (!update) {
155	    return;
156	  }
157	
158	  // Accumulate basic token counts
159	  target.total = addNumbers(target.total, update.total);
160	  target.prompt = addNumbers(target.prompt, update.prompt);
161	  target.completion = addNumbers(target.completion, update.completion);
162	  target.cached = addNumbers(target.cached, update.cached);
163	  // Note: We don't accumulate numRequests from the update for assertions
164	  // to maintain separation between provider and assertion request counts
165	
166	  // Handle completion details
167	  if (update.completionDetails) {
168	    target.completionDetails = accumulateCompletionDetails(
169	      target.completionDetails,
170	      update.completionDetails,
171	    );
172	  }
173	}
