175	/**
176	 * Accumulate token usage from a response, handling the common pattern of
177	 * incrementing numRequests when no token usage is provided.
178	 * @param target Object to update
179	 * @param response Response that may contain token usage
180	 */
181	export function accumulateResponseTokenUsage(
182	  target: TokenUsage,
183	  response: { tokenUsage?: Partial<TokenUsage> } | undefined,
184	  options?: { countAsRequest?: boolean },
185	): void {
186	  const countAsRequest = options?.countAsRequest ?? true;
187	
188	  if (response?.tokenUsage) {
189	    if (countAsRequest) {
190	      accumulateTokenUsage(target, response.tokenUsage);
191	      // Increment numRequests if not already present in tokenUsage
192	      if (response.tokenUsage.numRequests === undefined) {
193	        target.numRequests = (target.numRequests ?? 0) + 1;
194	      }
195	    } else {
196	      // Preserve token totals while explicitly excluding request counting.
197	      const tokenUsageWithoutRequests: Partial<TokenUsage> = {
198	        ...response.tokenUsage,
199	        numRequests: undefined,
200	      };
201	      accumulateTokenUsage(target, tokenUsageWithoutRequests);
202	    }
203	  } else if (response && countAsRequest) {
204	    // Only increment numRequests if we got a response but no token usage
205	    target.numRequests = (target.numRequests ?? 0) + 1;
206	  }
207	}
