209	/**
210	 * Normalize token usage from a provider response into a standard TokenUsage object.
211	 * Provides default values for all fields if not present in the response.
212	 * @param tokenUsage Token usage from provider response (may be partial or undefined)
213	 * @returns Fully populated TokenUsage object with defaults
214	 */
215	export function normalizeTokenUsage(
216	  tokenUsage: Partial<TokenUsage> | undefined,
217	): Required<TokenUsage> {
218	  return {
219	    total: tokenUsage?.total || 0,
220	    prompt: tokenUsage?.prompt || 0,
221	    completion: tokenUsage?.completion || 0,
222	    cached: tokenUsage?.cached || 0,
223	    numRequests: tokenUsage?.numRequests || 0,
224	    completionDetails: tokenUsage?.completionDetails || createEmptyCompletionDetails(),
225	    assertions: tokenUsage?.assertions || createEmptyAssertions(),
226	  };
