[metadata] {"filePath": "/workspace/repo/src/commands/eval.ts", "oldString": "export async function doEval(
  cmdObj: Partial<CommandLineOptions & Command>,
  defaultConfig: Partial<UnifiedConfig>,
  defaultConfigPath: string | undefined,", "newString": "/**
 * Resolve prompt-suggestion options into the `EvaluateOptions` passed to `evaluate()`.
 *
 * Precedence (highest first):
 *   1. `--suggest-prompts <N>` (a positive integer) which both enables suggestions
 *      and sets the count, overriding an explicit `generateSuggestions=false`.
 *   2. Runtime `cmdObj` options passed directly by the caller.
 *   3. `commandLineOptions` from the config file.
 *   4. `evaluateOptions` (runtime options merged with the config `evaluateOptions`).
 *
 * `suggestionsCount` is resolved independently of `generateSuggestions`, so a
 * config-provided count is preserved even when suggestions are disabled.
 */
function resolveSuggestionOptions(
  options: EvaluateOptions,
  cmdObj: Partial<CommandLineOptions & Command>,
  commandLineOptions: Record<string, any> | undefined,
  evaluateOptions: EvaluateOptions,
): void {
  const rawSuggestPrompts = (cmdObj as Partial<EvalCommandOptions>).suggestPrompts;
  const suggestPromptsCount = Number(rawSuggestPrompts);
  const hasSuggestPrompts =
    rawSuggestPrompts !== undefined &&
    rawSuggestPrompts !== null &&
    Number.isInteger(suggestPromptsCount) &&
    suggestPromptsCount > 0;

  const generateSuggestions = hasSuggestPrompts
    ? true
    : (cmdObj.generateSuggestions ??
      commandLineOptions?.generateSuggestions ??
      evaluateOptions.generateSuggestions);

  const suggestionsCount = hasSuggestPrompts
    ? suggestPromptsCount
    : (cmdObj.suggestionsCount ??
      commandLineOptions?.suggestionsCount ??
      evaluateOptions.suggestionsCount);

  if (generateSuggestions === undefined) {
    delete options.generateSuggestions;
  } else {
    options.generateSuggestions = generateSuggestions;
  }

  if (suggestionsCount === undefined) {
    delete options.suggestionsCount;
  } else {
    options.suggestionsCount = suggestionsCount;
  }
}

export async function doEval(
